import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Img } from '../remotionShim';


export type ComponentNameProps = Record<string, any>;

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 10,
  bannerBackgroundColor = "#000000",
  bannerHeight = 250,
  logoImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/207b3d7244174933b0db3162b07a3cf8.png",
  logoScale = 1.0,
  gapBetweenLogos = 150,
  scrollSpeed = 1.0,
  scrollDirection = "left",
  bannerRotation = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Handle transparent background safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Banner Entrance and Exit Physics
  const enterSpring = spring({
    frame,
    fps,
    config: { damping: 15, mass: 1.2 },
  });

  const outFrame = Math.max(fps / 2, durationInSeconds * fps - fps);
  const exitSpring = spring({
    frame: Math.max(0, frame - outFrame),
    fps,
    config: { damping: 15, mass: 1.2 },
  });

  // Calculate start/end positions based on direction. 
  // We use 2x screen width to ensure the banner completely clears the screen, even if heavily rotated.
  const startX = scrollDirection === "left" ? width * 2 : -width * 2;
  const endX = scrollDirection === "left" ? -width * 2 : width * 2;

  const bannerEnterX = interpolate(enterSpring, [0, 1], [startX, 0]);
  const bannerExitX = interpolate(exitSpring, [0, 1], [0, endX]);

  // Summing the two translates elegantly combines the enter and exit states without 1-frame glitches
  const currentBannerX = bannerEnterX + bannerExitX;

  // Infinite Marquee Logic
  // We establish a fixed unit width so we can seamlessly loop it via modulo arithmetic
  const ITEM_WIDTH = (bannerHeight * 2 * logoScale) + gapBetweenLogos;
  const BANNER_WIDTH = width * 3; // Extra wide to handle corner-to-corner coverage during rotation
  const NUM_ITEMS = Math.ceil(BANNER_WIDTH / ITEM_WIDTH) + 4; // Add generous buffer for wrapping bounds
  const itemsArray = new Array(NUM_ITEMS).fill(0);

  const pixelsPerFrame = (width / (fps * 4)) * scrollSpeed;
  const baseTranslate = (frame * pixelsPerFrame) % ITEM_WIDTH;
  
  // Wrap exactly at the boundary of 1 item to create an invisible infinite loop
  const innerTranslateX = scrollDirection === "left" ? -baseTranslate : baseTranslate;

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        overflow: "hidden", 
        display: "flex", 
        alignItems: "center", 
        justifyContent: "center",
        transition: "none"
      }}
    >
      {/* Structural Banner Container */}
      <div
        style={{
          position: "absolute",
          width: BANNER_WIDTH,
          height: bannerHeight,
          backgroundColor: bannerBackgroundColor,
          left: -width, // Pre-center the oversized banner horizontally
          transform: `translateX(${currentBannerX}px) rotate(${bannerRotation}deg)`,
          display: "flex",
          alignItems: "center",
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* Inner Marquee Moving Track */}
        <div
          style={{
            position: "absolute",
            left: -ITEM_WIDTH * 2, // Shift left by 2 items to ensure no empty space exposes during right-ward wrapping
            display: "flex",
            flexDirection: "row",
            width: ITEM_WIDTH * NUM_ITEMS,
            transform: `translateX(${innerTranslateX}px)`,
            transition: "none",
          }}
        >
          {itemsArray.map((_, i) => (
            <div
              key={i}
              style={{
                width: ITEM_WIDTH,
                height: bannerHeight,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                flexShrink: 0,
              }}
            >
              <Img
                src={logoImage}
                style={{
                  width: bannerHeight * 2 * logoScale,
                  height: bannerHeight * 0.8 * logoScale,
                  objectFit: "contain",
                }}
              />
            </div>
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;